import{_ as t,o as a,c as d,Q as r}from"./chunks/framework.48927342.js";const m=JSON.parse('{"title":"回复晚餐邀请邮件","description":"","frontmatter":{},"headers":[],"relativePath":"zh/more/maltese/practice/emails/06-dinner-reply.md","filePath":"zh/more/maltese/practice/emails/06-dinner-reply.md"}'),e={name:"zh/more/maltese/practice/emails/06-dinner-reply.md"},o=r('<h1 id="回复晚餐邀请邮件" tabindex="-1">回复晚餐邀请邮件 <a class="header-anchor" href="#回复晚餐邀请邮件" aria-label="Permalink to &quot;回复晚餐邀请邮件&quot;">​</a></h1><p><strong>场景：</strong> Mark 接受 Anna 的晚餐邀请，并主动提出带甜点。</p><h2 id="邮件头部" tabindex="-1">邮件头部 <a class="header-anchor" href="#邮件头部" aria-label="Permalink to &quot;邮件头部&quot;">​</a></h2><p><strong>Lil（收件人 To）：</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Mingħand（发件人 From）：</strong> <a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a><strong>Data（日期）：</strong> 14 ta&#39; Ottubru 2026 <strong>Suġġett（主题）：</strong> Risposta għall-ikla ta&#39; filgħaxija</p><h2 id="邮件全文" tabindex="-1">邮件全文 <a class="header-anchor" href="#邮件全文" aria-label="Permalink to &quot;邮件全文&quot;">​</a></h2><blockquote><p><strong>Lil:</strong> <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a><strong>Mingħand:</strong> <a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a><strong>Data:</strong> 14 ta&#39; Ottubru 2026 <strong>Suġġett:</strong> Risposta għall-ikla ta&#39; filgħaxija</p><p>Għażiża Anna,</p><p>Grazzi tal-istedina għall-ikla ta&#39; filgħaxija.</p><p>Iva, se niġi nhar il-Ġimgħa.</p><p>Se nasal fis-sebgħa.</p><p>M&#39;għandi l-ebda preferenza għall-ikel.</p><p>Nista&#39; nġib xi ħaġa għad-deżerta?</p><p>Se nġib kejk żgħir.</p><p>Nistenna bil-ħerqa li niltaqa&#39; mal-ħbieb tiegħek.</p><p>Tislijiet, Mark</p></blockquote><h2 id="逐句翻译与逐词拆解" tabindex="-1">逐句翻译与逐词拆解 <a class="header-anchor" href="#逐句翻译与逐词拆解" aria-label="Permalink to &quot;逐句翻译与逐词拆解&quot;">​</a></h2><p><strong>Malti:</strong> Lil: <a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></p><p><strong>整句：</strong> 收件人（To）：anna.c@gmail.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Lil</td><td>收件人；给……</td><td>邮件头部&quot;To&quot;的马耳他语标签</td></tr><tr><td><a href="mailto:anna.c@gmail.com" target="_blank" rel="noreferrer">anna.c@gmail.com</a></td><td>邮箱地址</td><td>收件人（Anna）的邮箱</td></tr></tbody></table><p><strong>Malti:</strong> Mingħand: <a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a></p><p><strong>整句：</strong> 发件人（From）：mark.b@gmail.com</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Mingħand</td><td>发件人；来自……</td><td>邮件头部&quot;From&quot;的马耳他语标签，本义&quot;从……那里&quot;</td></tr><tr><td><a href="mailto:mark.b@gmail.com" target="_blank" rel="noreferrer">mark.b@gmail.com</a></td><td>邮箱地址</td><td>发件人（Mark）的邮箱</td></tr></tbody></table><p><strong>Malti:</strong> Data: 14 ta&#39; Ottubru 2026</p><p><strong>整句：</strong> 日期：2026 年 10 月 14 日</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Data</td><td>日期</td><td>邮件头部&quot;Date&quot;；马耳他语日期格式为&quot;日 ta&#39; 月 年&quot;</td></tr><tr><td>14</td><td>十四</td><td>日期中的日</td></tr><tr><td>ta&#39;</td><td>……的</td><td>连接日和月份</td></tr><tr><td>Ottubru</td><td>十月</td><td>月份名</td></tr></tbody></table><p><strong>Malti:</strong> Suġġett: Risposta għall-ikla ta&#39; filgħaxija</p><p><strong>整句：</strong> 主题：回复晚餐邀请</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Suġġett</td><td>主题</td><td>邮件头部&quot;Subject&quot;</td></tr><tr><td>Risposta</td><td>回复；答复</td><td>阴性名词</td></tr><tr><td>għall-ikla</td><td>针对晚餐；回应晚餐邀请</td><td><code>għal</code> + <code>l-ikla</code> 的缩合形式</td></tr><tr><td>ta&#39;</td><td>……的；在……时段</td><td>连接名词和时间表达</td></tr><tr><td>filgħaxija</td><td>在晚上</td><td>时间表达</td></tr></tbody></table><p><strong>Malti:</strong> Għażiża Anna,</p><p><strong>整句：</strong> 亲爱的安娜：</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Għażiża</td><td>亲爱的</td><td>阴性单数称呼形式</td></tr><tr><td>Anna</td><td>安娜</td><td>人名</td></tr></tbody></table><h3 id="_1" tabindex="-1">1. <a class="header-anchor" href="#_1" aria-label="Permalink to &quot;1.&quot;">​</a></h3><p><strong>Malti:</strong> Grazzi tal-istedina għall-ikla ta&#39; filgħaxija.</p><p><strong>整句：</strong> 感谢你邀请我参加晚餐。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Grazzi</td><td>谢谢</td><td>礼貌用语</td></tr><tr><td>tal-istedina</td><td>因为邀请；邀请的</td><td><code>ta&#39;</code> 与定冠词缩合</td></tr><tr><td>għall-ikla</td><td>去吃饭；参加晚餐</td><td><code>għal</code> 与定冠词缩合</td></tr><tr><td>ta&#39;</td><td>……的；在……时段</td><td>连接名词和时间表达</td></tr><tr><td>filgħaxija</td><td>在晚上</td><td>时间表达</td></tr></tbody></table><h3 id="_2" tabindex="-1">2. <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2.&quot;">​</a></h3><p><strong>Malti:</strong> Iva, se niġi nhar il-Ġimgħa.</p><p><strong>整句：</strong> 好的，我星期五会来。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Iva</td><td>是；好的</td><td>肯定回答</td></tr><tr><td>se</td><td>将；会</td><td>将来标记</td></tr><tr><td>niġi</td><td>我来</td><td>第一人称单数形式</td></tr><tr><td>nhar</td><td>在……那天</td><td>引出星期或日期</td></tr><tr><td>il-Ġimgħa</td><td>星期五</td><td>星期名称通常带定冠词</td></tr></tbody></table><h3 id="_3" tabindex="-1">3. <a class="header-anchor" href="#_3" aria-label="Permalink to &quot;3.&quot;">​</a></h3><p><strong>Malti:</strong> Se nasal fis-sebgħa.</p><p><strong>整句：</strong> 我会七点到。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Se</td><td>将；会</td><td>将来标记</td></tr><tr><td>nasal</td><td>我到达</td><td>第一人称单数形式</td></tr><tr><td>fis-sebgħa</td><td>在七点</td><td><code>f&#39;</code> 与钟点定冠词形式缩合</td></tr></tbody></table><h3 id="_4" tabindex="-1">4. <a class="header-anchor" href="#_4" aria-label="Permalink to &quot;4.&quot;">​</a></h3><p><strong>Malti:</strong> M&#39;għandi l-ebda preferenza għall-ikel.</p><p><strong>整句：</strong> 我对食物没有特别偏好。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>M&#39;għandi</td><td>我没有</td><td><code>ma għandix</code> 的缩合/否定形式之一</td></tr><tr><td>l-ebda</td><td>没有任何；不……</td><td>否定限定表达</td></tr><tr><td>preferenza</td><td>偏好</td><td>阴性名词</td></tr><tr><td>għall-ikel</td><td>对食物；关于吃的</td><td><code>għal</code> 与定冠词缩合</td></tr></tbody></table><h3 id="_5" tabindex="-1">5. <a class="header-anchor" href="#_5" aria-label="Permalink to &quot;5.&quot;">​</a></h3><p><strong>Malti:</strong> Nista&#39; nġib xi ħaġa għad-deżerta?</p><p><strong>整句：</strong> 我可以带点甜点来吗？</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nista&#39;</td><td>我可以吗</td><td>第一人称单数形式</td></tr><tr><td>nġib</td><td>我带来</td><td>第一人称单数形式</td></tr><tr><td>xi</td><td>一些；某个</td><td>不定限定词</td></tr><tr><td>ħaġa</td><td>东西</td><td>阴性名词</td></tr><tr><td>għad-deżerta</td><td>用作甜点；作为甜点</td><td><code>għal</code> 与定冠词缩合</td></tr></tbody></table><h3 id="_6" tabindex="-1">6. <a class="header-anchor" href="#_6" aria-label="Permalink to &quot;6.&quot;">​</a></h3><p><strong>Malti:</strong> Se nġib kejk żgħir.</p><p><strong>整句：</strong> 我会带一个小蛋糕。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Se</td><td>将；会</td><td>将来标记</td></tr><tr><td>nġib</td><td>我带来</td><td>第一人称单数形式</td></tr><tr><td>kejk</td><td>蛋糕</td><td>阳性名词</td></tr><tr><td>żgħir</td><td>小的</td><td>阳性单数形式，与 <code>kejk</code> 一致</td></tr></tbody></table><h3 id="_7" tabindex="-1">7. <a class="header-anchor" href="#_7" aria-label="Permalink to &quot;7.&quot;">​</a></h3><p><strong>Malti:</strong> Nistenna bil-ħerqa li niltaqa&#39; mal-ħbieb tiegħek.</p><p><strong>整句：</strong> 我期待见到你的朋友们。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Nistenna</td><td>我等待；我期待</td><td>第一人称单数形式</td></tr><tr><td>bil-ħerqa</td><td>热切地；期待地</td><td>固定副词短语</td></tr><tr><td>li</td><td>……；引出从句</td><td>连词</td></tr><tr><td>niltaqa&#39;</td><td>我见面</td><td>第一人称单数形式</td></tr><tr><td>mal-ħbieb</td><td>和朋友们</td><td><code>ma&#39;</code> 与定冠词缩合</td></tr><tr><td>tiegħek</td><td>你的</td><td>第二人称单数所有格</td></tr></tbody></table><p><strong>Malti:</strong> Tislijiet, Mark</p><p><strong>整句：</strong> 此致敬意，马克（邮件落款）。</p><table><thead><tr><th>词语</th><th>中文含义</th><th>说明</th></tr></thead><tbody><tr><td>Tislijiet</td><td>此致敬意；致以问候</td><td>正式邮件/信件落款用语，本义&quot;问候/致意&quot;</td></tr><tr><td>Mark</td><td>马克</td><td>人名</td></tr></tbody></table>',53),l=[o];function i(n,h,s,g,b,p){return a(),d("div",null,l)}const k=t(e,[["render",i]]);export{m as __pageData,k as default};
